// EXP-551 — the emoji dataset's PURE half: the index and the ranked search.
//
// The dataset is the shared one generated by packages/emoji into
// `emoji.generated.json` (labels, GitHub shortcodes, tags; same file on
// iOS/Android/desktop, so every client searches the same names). The app owns
// the lazy load, the recents and the `:shortcode` typeahead (its
// `lib/emoji.ts` re-exports this half); this file only indexes and searches.
// Always the BASE record: EXP-600 dropped the skin-tone picker on every
// client (the dataset's `k` variants are deliberately unread).
//
// The ranking rules below are mirrored by hand on the three native clients
// (EmojiCatalog.swift / EmojiCatalog.kt / emoji.rs).

import type { EmojiDataset, EmojiRecord } from "@exp/emoji"

export type { EmojiDataset, EmojiRecord }

export interface EmojiGroup {
  index: number
  label: string
  emojis: EmojiRecord[]
}

export interface EmojiData {
  dataset: EmojiDataset
  groups: EmojiGroup[]
  /** Lowercased shortcode → record (first record wins on collisions). */
  byShortcode: Map<string, EmojiRecord>
  /** Base unicode → record. */
  byUnicode: Map<string, EmojiRecord>
}

export function indexEmojiData(dataset: EmojiDataset): EmojiData {
  const groups: EmojiGroup[] = dataset.groups.map((label, index) => ({
    index,
    label,
    emojis: [],
  }))
  const byShortcode = new Map<string, EmojiRecord>()
  const byUnicode = new Map<string, EmojiRecord>()
  for (const emoji of dataset.emojis) {
    groups[emoji.g]?.emojis.push(emoji)
    byUnicode.set(emoji.u, emoji)
    for (const code of emoji.s) {
      const key = code.toLowerCase()
      if (!byShortcode.has(key)) byShortcode.set(key, emoji)
    }
  }
  return { dataset, groups, byShortcode, byUnicode }
}

// ── Search ──

/**
 * Ranked search: shortcode prefix > label prefix > tag prefix > label/tag
 * substring; ties keep dataset order. Empty query → nothing.
 */
export function searchEmoji(
  data: EmojiData,
  query: string,
  limit: number
): EmojiRecord[] {
  const q = query.trim().toLowerCase().replace(/^:|:$/g, ``)
  if (!q) return []
  const scored: { emoji: EmojiRecord; rank: number; order: number }[] = []
  const emojis = data.dataset.emojis
  for (let order = 0; order < emojis.length; order++) {
    const emoji = emojis[order]
    const rank = rankEmoji(emoji, q)
    if (rank !== null) scored.push({ emoji, rank, order })
  }
  scored.sort((a, b) => a.rank - b.rank || a.order - b.order)
  return scored.slice(0, limit).map((s) => s.emoji)
}

function rankEmoji(emoji: EmojiRecord, q: string): number | null {
  const label = emoji.l.toLowerCase()
  if (emoji.s.some((code) => code.toLowerCase() === q)) return 0
  if (emoji.s.some((code) => code.toLowerCase().startsWith(q))) return 1
  if (label.startsWith(q)) return 2
  if (emoji.t.some((tag) => tag === q || tag.startsWith(q))) return 3
  if (label.includes(q) || emoji.t.some((tag) => tag.includes(q))) return 4
  return null
}

/** Exact shortcode lookup (`tada` → 🎉), used by the `:tada:` auto-commit. */
export function findEmojiByShortcode(
  data: EmojiData,
  shortcode: string
): EmojiRecord | null {
  return data.byShortcode.get(shortcode.toLowerCase()) ?? null
}
